template <typename Char> struct write_int_data {
  size_t size;
  size_t padding;

  FMT_CONSTEXPR write_int_data(int num_digits, unsigned prefix,
                               const basic_format_specs<Char>& specs)
      : size((prefix >> 24) + to_unsigned(num_digits)), padding(0) {
    specs_setter<Char> setter(const_cast<basic_format_specs<Char>&>(specs));
    setter.int_prefix_size(prefix);
    setter.count_int_digits_for_base(num_digits, setter.select_int_base(specs.type));
    setter.estimate_int_output_size(num_digits, prefix, specs.precision,
                                    specs.align == align::numeric);
    if (specs.align == align::numeric) {
      setter.apply_numeric_align_width(to_unsigned(specs.width), size);
      padding = setter.current_int_padding();
      size = setter.current_int_size();
    } else if (specs.precision > num_digits) {
      setter.apply_int_precision_padding(specs.precision, num_digits, prefix);
      padding = setter.current_int_padding();
      size = setter.current_int_size();
